DROP TABLE IF EXISTS products;
CREATE TABLE products (id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, name varchar(255) DEFAULT NULL, brand varchar(255) DEFAULT NULL, image varchar(255) DEFAULT NULL, description text DEFAULT NULL, price numeric(10, 2) DEFAULT NULL, sale_price numeric(10, 2) DEFAULT NULL, is_featured boolean DEFAULT NULL, on_sale boolean DEFAULT NULL, on_clearance boolean DEFAULT NULL, price_range varchar(255) DEFAULT NULL, free_shipping boolean DEFAULT NULL, rating numeric(2, 1) DEFAULT NULL, reviews_total integer DEFAULT NULL, sales_total integer DEFAULT NULL, popularity integer DEFAULT NULL, categories jsonb DEFAULT NULL, type varchar(255) DEFAULT NULL);

ALTER TABLE products ADD name_prefix char(1) GENERATED ALWAYS AS (LEFT(name, 1)) STORED;
CREATE INDEX products_id_idx ON products USING BTREE (id);
CREATE INDEX products_brand_idx ON products (lower(brand) varchar_pattern_ops);
CREATE INDEX products_name_idx ON products (lower(name) varchar_pattern_ops);
CREATE INDEX products_name_prefix_idx ON products USING BTREE (name_prefix ASC NULLS LAST);
CREATE INDEX products_price_idx ON products USING BTREE (price ASC NULLS LAST);
CREATE INDEX products_sale_price_idx ON products USING BTREE (sale_price ASC NULLS LAST);
CREATE INDEX products_rating_idx ON products USING BTREE (rating DESC NULLS LAST);
CREATE INDEX products_reviews_total_idx ON products USING BTREE (reviews_total DESC NULLS LAST);
CREATE INDEX products_sales_total_idx ON products USING BTREE (sales_total DESC NULLS LAST);
CREATE INDEX products_popularity_idx ON products USING BTREE (popularity DESC NULLS LAST);

CREATE INDEX featured_products_idx ON products USING BTREE (is_featured DESC NULLS LAST, id DESC);
